import{_ as n,l as s,o as a,c as o,v as i,p as l,x as t,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"启发式与偏差","description":"","frontmatter":{"title":"启发式与偏差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/heuristics-biases.md","filePath":"econ/heuristics-biases.md","lastUpdated":1789023840000}'),c={name:"econ/heuristics-biases.md"};function A(B,e,h,_,m,u){const r=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=i('<h1 id="启发式与偏差" tabindex="-1">启发式与偏差 <a class="header-anchor" href="#启发式与偏差" aria-label="Permalink to &quot;启发式与偏差&quot;">​</a></h1><div class="epigraph"><p>代表性、可得性、锚定：用便宜的线索代替概率计算，偏差是捷径的影子，不是随机噪声。</p><footer>—— Tversky and Kahneman, Judgment under Uncertainty: Heuristics and Biases, Science, 1974</footer></div><p><a href="/econ/overconfidence">上一课</a>给出校准失败。本课缺口是机制：人用启发式生成概率，于是系统性地偏。不把过度自信再定义一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贝叶斯要求似然与先验。Tversky 与 Kahneman（1974）列出三条捷径。代表性：用「像不像典型」代替基率与样本量，导致基率忽视、合取谬误。可得性：用容易想起的例子代替频率，媒体暴露扭曲灾难概率。锚定与调整：从任意起点调整不足，估计依赖无关锚。这些偏差不是对 <a href="/econ/expected-utility">vNM</a> 的再拒绝，而是对信念输入的拒绝。</p><p>家庭金融：用近期回报代表未来（代表性）制造趋势追逐；用身边炒股故事代表参与收益（可得性）；用买入价当锚（与参考点重叠但起源是判断而非偏好）。</p><p><span class="marginnote">合取谬误：Linda 是银行出纳且女权主义者，被判比「银行出纳」更可能。概率上不可能，代表性上更像故事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：基率问题、字母频率、轮盘给出的锚。预测是方向性的：锚高则估计高，生动事件则概率高。本课不估计启发式的神经基础。与概率加权的分工：加权是已知 \\(p\\) 仍扭曲；启发式是 \\(p\\) 本身被错估。</p>',9)),(a(),l(d,null,{default:t(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OC%5B%22%E8%BF%87%E5%BA%A6%E8%87%AA%E4%BF%A1%3A%20%E7%B2%BE%E5%BA%A6%E8%BF%87%E9%AB%98%22%5D%20--%3E%20H%5B%22%E5%90%AF%E5%8F%91%E5%BC%8F%3A%20%E7%94%A8%E7%BA%BF%E7%B4%A2%E4%BB%A3%E6%9B%BF%E8%B4%9D%E5%8F%B6%E6%96%AF%22%5D%0A%20%20H%20--%3E%20REP%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%3A%20%E5%BF%BD%E8%A7%86%E5%9F%BA%E7%8E%87%22%5D%0A%20%20H%20--%3E%20AV%5B%22%E5%8F%AF%E5%BE%97%E6%80%A7%3A%20%E7%94%9F%E5%8A%A8%E4%BB%A3%E6%9B%BF%E9%A2%91%E7%8E%87%22%5D%0A%20%20H%20--%3E%20ANC%5B%22%E9%94%9A%E5%AE%9A%3A%20%E8%B0%83%E6%95%B4%E4%B8%8D%E8%B6%B3%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是属性替换：目标属性难算，用启发属性代替。偏差因此可预测，可被框架放大（生动描述提高可得性）。资产价格若由使用同一启发式的人加总，会有动量与反转——BSV 用代表性与保守性写模型，后单元再接。本课只给微观判断。</p><p>与有限理性的接口：启发式可以是对计算成本的最优响应（后课 Simon），也可以是固定的心理程序。1974 年论文取后者：偏差相对规范模型被定义。</p><p>基率忽视不是把先验设成无信息：人往往用代表性完全替换贝叶斯分子分母里的基率。锚定的起点可以无关（随机轮盘），调整不足使估计继承锚——这与买入价参考点近亲，但起源是判断数字，不是得失编码。可得性让最近的崩盘故事抬高主观尾部，保险需求上升，不必先动 \\(w(p)\\)。BSV 后课会把代表性与保守写成价格动态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Gigerenzer 强调生态理性：在正确环境下启发式可以更准。本栏补层仍用规范贝叶斯当对照，否则「偏差」没有定义。现场经验、统计培训能减弱部分效应，不能据此宣称市场无偏差。本课不把三条写成完备分类。</p><p>后课默认：判断偏差来自启发式；有限理性给出「为何不用完整贝叶斯」的计算理由。</p><p>属性替换生成可预测偏差：代表性压基率，可得性用生动代替频率，锚定调整不足。</p><p>与概率加权分工：启发式错估输入，加权扭曲已知 \\(p\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代表性、可得性、锚定系统性地错估 \\(p\\)。</li><li>与概率加权分工：一个错估输入，一个扭曲已知 \\(p\\)。</li><li>不重推期望效用；信念侧的缺口在此。</li><li>合取谬误是代表性的经典。</li><li>BSV 后课把代表性与保守放进价格。</li><li>出处：Tversky and Kahneman, <em>Science</em> 1974。</li></ul>',11))])}const b=n(c,[["render",A]]);export{T as __pageData,b as default};
